from pathlib import Path
import json,hashlib,zipfile
root=Path(__file__).resolve().parents[2];out=root/'production/chapter01';refs=out/'private/style-references'
block='Создай одну законченную цветную иллюстрацию для исторического рассказа HIStory. Вертикальная композиция 3:4, непрозрачный фон, изображение заполняет весь кадр. Ноябрь 1990 года, без современных предметов. Манера ранних рисунков серии — фактурный ретро-комикс с реалистичной анатомией. Уверенный тёмно-коричневый, почти чёрный контур переменной толщины; внутренние линии тоньше. Объём собирается крупными цельными пятнами тени и направленной штриховкой по форме лица, ткани и предметов. Матовые плотные цветовые плоскости, тонкая фактура печатной бумаги; зерно не закрывает глаза и мелкие детали. Палитра: глубокие тёмно-синие и дымчато-серые тени, тёплая охра, песочно-кремовый свет, умеренные оливковые акценты. Цветность полноценная, без сплошной сепии. Освещение соответствует сцене; янтарный свет появляется только от реальных ламп. Человеческие пропорции и сдержанная мимика, без увеличенных глаз и утяжелённой челюсти. Старые рисунки S01–S03 задают только линию, штрих, фактуру и отношения цветов; не копируй их лица, одежду, погоду, предметы и сюжет. Без размытых полос, рваной бумажной рамки, коллажа, декоративных звёзд, речевых пузырей, акварельных разводов, аниме и глянцевого 3D. Все 41 изображения выглядят частями одной рисованной книги, понятными на экране телефона.'
block=block.replace('возраст18','возраст 18').replace('глянцевого3D','глянцевого 3D').replace('Все41','Все 41')
style={
 'schemaVersion':1,'id':'history-early-ink-retro-v1','name':'Фактурный ретро-комикс HIStory','format':'3:4',
 'basis':'Визуально осмотренные ранние иллюстрации проекта, только манера рисования.',
 'promptBlock':block,
 'palette':[{'name':'Глубокая тёмно-синяя тень','hex':'#172B3B'}, {'name':'Дымчатый синий','hex':'#58717A'},
            {'name':'Охра','hex':'#BB8657'},{'name':'Кремовый свет','hex':'#E8D3AC'},
            {'name':'Ламповый янтарь','hex':'#E2B56E'},{'name':'Тёмный контур','hex':'#2B241F'},
            {'name':'Приглушённый оливковый','hex':'#646B55'}],
 'paletteStatus':'Подобранные визуально ориентиры для рисунка; не документальные цвета предметов и не измерение исходных пикселей.',
 'referencePriority':['Подтверждённые факты и отдельная сцена','Новые фотографии R01/R02/R04 для личности и одежды','Стилевые S01–S03 только для манеры'],
 'styleReferences':[],
 'isRenderedImage':False
}
for code,name,original,use in [
 ('S01','S01-early-commissariat.webp','public/assets/commissariat.webp','Контур, тёмные пятна одежды, охра стен и штриховка.'),
 ('S02','S02-early-cover.webp','public/assets/cover.webp','Обработка лица линией и штрихом, отношение тёмно-синего к кремовому и охре.'),
 ('S03','S03-early-train.webp','public/assets/train.webp','Плоско нанесённый матовый цвет, рисунок интерьера и тёплая фактура.')]:
    f=refs/name;assert f.is_file()
    style['styleReferences'].append({'id':code,'file':f.relative_to(out).as_posix(),'historicalAssetPath':original,
                                     'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'use':use,'role':'style_only'})
(out/'visual-style.json').write_text(json.dumps(style,ensure_ascii=False,indent=2)+'\n')
(out/'style-master-prompt.txt').write_text(block+'\n')
md=['# Единый стиль иллюстраций HIStory','',
'Основа — ранние рисунки серии: фактурный ретро-комикс с реалистичными пропорциями. Манера взята из осмотренных `commissariat.webp`, `cover.webp` и `train.webp`. Эти картинки используются как образцы рисования; новая глава сохраняет актуальные факты, фотографии автора и исправленную одежду.','',
'## Линия и объём','',
'Внешний контур тёмно-коричневый, почти чёрный, с живой переменной толщиной. Внутренние детали тоньше. Тени собраны в понятные тёмные пятна; мелкая штриховка следует форме скулы, шеи, складок и металлических деталей. Силуэт хорошо различим на телефоне.','',
'Лицо остаётся лицом18-летнего автора с R01. Не копировать тяжёлую челюсть или причёску старого нарисованного моряка и не превращать нового героя в карикатуру. Эмоции задаёт сцена.','',
'## Цвет и фактура','',
'Полноценный приглушённый цвет: синие тени, охристые и кремовые светлые области, умеренные оливковые детали. Матовая поверхность, тонкое печатное зерно; штрих и контур важнее зернистого фильтра. Фактура не закрывает лицо, руки, рисунок формы и важные предметы.','',
'| Роль | Ориентир цвета |','|---|---|']
for x in style['palette']:md.append(f"| {x['name']} | `{x['hex']}` |")
md+=['',style['paletteStatus'],'',
'Подтверждённые цвета сохраняются: гражданские джинсы чёрные, сменные широкие брюки тёмно-синие. Синяя палитра освещения не должна превращать чёрные джинсы в синие. Цвета куртки и обуви остаются последовательной художественной реконструкцией.','',
'## Свет по сценам','',
'| Сцены | Решение |','|---|---|',
'| Военкомат и дневной двор | Прохладный естественный свет, читаемые охристые полутона кожи; без золотого ореола. |',
'| Поезд | Мягкий янтарный свет ламп на фоне глубоких синих теней; не превращать вагон в праздничную сцену. |',
'| Симферопольская казарма | Приглушённые охристо-серые стены и тёмно-синие тени; ночью слабый бытовой свет, лица различимы. |',
'| Спарринг | Ясные силуэты и опоры ног, без комедийных гримас, звёздочек удара и летящей фуражки. |',
'| Прибытие в Севастополь | Ночная сине-охристая среда, мягкие станционные огни. Погода тёплая; снег и мороз не добавляются. |','',
'## Как использовать старые картинки','',
'Сначала прикреплять актуальный портрет R01. Затем можно добавить один стилевой рисунок S01, S02 или S03. В запросе явно разделять роли: R — лицо/форма, S — только способ рисования. Для связанных сцен полезен также уже одобренный новый рисунок той же локации.','',
'| Код | Источник | Что брать |','|---|---|']
for x in style['styleReferences']:md.append(f"| {x['id']} | `{x['file']}` | {x['use']} |")
md+=['',
'Из старых изображений не переносятся сюжет, персонажи, морская форма до её выдачи, широкие улыбки, политическая символика, читаемые вывески, погода и неподтверждённые предметы. Размытые полосы и бумажные рамки ранних файлов — элементы прежней подачи, они исключены из новой серии.','',
'Пользователь отдельно разрешил использовать стилистику ранних рисунков. Это не отменяет удаление прежней истории и не возвращает старые иллюстрации в публичные активы приложения. Стилевые копии находятся в ignored `private/style-references/`.','',
'## Готовый блок для GPT','', '```text',block,'```','',
'Этот блок уже включён в каждый из41 подробного промпта в `gpt-image-prompts.md`. Отдельно добавлять его повторно не нужно. Артефакт описывает стиль; новые иллюстрации по нему ещё не генерировались.']
text='\n'.join(md).rstrip()+'\n';text=text.replace('лицом18','лицом 18').replace('из41','из 41')
(out/'style-bible.md').write_text(text)
readme=('СТИЛЕВЫЕ РЕФЕРЕНСЫ HIStory\n\n'
        'S01–S03 — прежние иллюстрации проекта. Использовать только контур, штриховку, фактуру и палитру.\n'
        'Не копировать лица, одежду, эмоции, сюжет, символику, подписи и размытые полосы.\n'
        'Новые фотографии R01/R02/R04 определяют лицо и форму; актуальный текст определяет события.\n'
        'Для GPT достаточно одного S-референса вместе с портретом R01 и выбранным сюжетным промптом.\n'
        'MASTER-STYLE.txt содержит стилевой блок. В41 сюжетном промпте он уже включён.\n'
        'Референсы лица из переписки в этот архив не включены.\n')
with zipfile.ZipFile(out/'private/style-reference-pack.zip','w',compression=zipfile.ZIP_DEFLATED) as z:
    z.writestr('README.txt',readme.replace('В41','В 41'))
    z.writestr('MASTER-STYLE.txt',block+'\n')
    for x in style['styleReferences']:z.write(out/x['file'],arcname=Path(x['file']).name)
print('Created style guide, shared style JSON, master prompt and private3-image reference pack.')
